from collections import Counter

class Solution:
    def stoneGameIX(self, stones: list[int]) -> bool:
        cnt = Counter(x % 3 for x in stones)
        c0, c1, c2 = cnt[0], cnt[1], cnt[2]
        if c0 % 2 == 0:
            return c1 >= 1 and c2 >= 1
        else:
            return abs(c1 - c2) > 2

class Solution {
public:
    bool stoneGameIX(vector<int>& stones) {
        vector<int> cnt(3, 0);
        for (int x : stones) cnt[x % 3]++;
        int c0 = cnt[0], c1 = cnt[1], c2 = cnt[2];
        if (c0 % 2 == 0) {
            return c1 >= 1 && c2 >= 1;
        } else {
            return abs(c1 - c2) > 2;
        }
    }
};

class Solution {
    public boolean stoneGameIX(int[] stones) {
        int[] cnt = new int[3];
        for (int x : stones) cnt[x % 3]++;
        int c0 = cnt[0], c1 = cnt[1], c2 = cnt[2];
        if (c0 % 2 == 0) {
            return c1 >= 1 && c2 >= 1;
        } else {
            return Math.abs(c1 - c2) > 2;
        }
    }
}

var stoneGameIX = function(stones) {
  const cnt = [0, 0, 0];
  for (const x of stones) cnt[x % 3]++;
  const [c0, c1, c2] = cnt;
  if (c0 % 2 === 0) {
    return c1 >= 1 && c2 >= 1;
  } else {
    return Math.abs(c1 - c2) > 2;
  }
};
